  {
    "id": "013_app_releases.sql",
    "sql": "-- Mobile Application Releases & OTA Updates (Spec 2.15 & In-App OTA Updater)\nCREATE TABLE IF NOT EXISTS app_releases (\n  id TEXT PRIMARY KEY,\n  version_name TEXT NOT NULL,\n  version_code INTEGER NOT NULL,\n  platform TEXT NOT NULL DEFAULT 'android', -- 'android', 'ios', 'universal'\n  file_name TEXT,\n  file_size INTEGER DEFAULT 0,\n  download_url TEXT NOT NULL,\n  release_notes TEXT,\n  mandatory INTEGER NOT NULL DEFAULT 0,\n  download_count INTEGER NOT NULL DEFAULT 0,\n  active INTEGER NOT NULL DEFAULT 1,\n  published_at INTEGER NOT NULL,\n  created_by TEXT DEFAULT 'admin'\n);\n\nCREATE INDEX IF NOT EXISTS idx_app_releases_version ON app_releases(version_code DESC, active);\n\n-- Default settings for OTA and iOS distribution\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('min_supported_version_code', '1', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('ios_testflight_url', '', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('ios_enterprise_manifest_url', '', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('github_repo_owner', 'Abdullah-rethink', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('github_repo_name', 'Office_tracker', 0, 'system');\n"
  },
  {
    "id": "014_desktop_workstations.sql",
    "sql": "-- Workstation Sessions, Desktop Presence, and Anomaly Monitoring\nCREATE TABLE IF NOT EXISTS workstation_sessions (\n  id TEXT PRIMARY KEY,\n  device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,\n  employee_id TEXT NOT NULL REFERENCES employees(id) ON DELETE CASCADE,\n  status TEXT NOT NULL DEFAULT 'ACTIVE',\n  session_date TEXT NOT NULL,\n  active_seconds INTEGER NOT NULL DEFAULT 0,\n  idle_seconds INTEGER NOT NULL DEFAULT 0,\n  break_seconds INTEGER NOT NULL DEFAULT 0,\n  lock_state TEXT NOT NULL DEFAULT 'UNLOCKED',\n  connected_bssid TEXT,\n  in_office INTEGER NOT NULL DEFAULT 0,\n  last_heartbeat_at INTEGER NOT NULL,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  UNIQUE(device_id, session_date)\n);\n\nCREATE INDEX IF NOT EXISTS idx_workstation_emp_date ON workstation_sessions(employee_id, session_date);\n\nCREATE TABLE IF NOT EXISTS process_anomalies (\n  id TEXT PRIMARY KEY,\n  employee_id TEXT NOT NULL REFERENCES employees(id) ON DELETE CASCADE,\n  device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,\n  process_name TEXT NOT NULL,\n  window_title TEXT,\n  duration_seconds INTEGER NOT NULL,\n  detected_at INTEGER NOT NULL,\n  resolved INTEGER NOT NULL DEFAULT 0,\n  notes TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_anomalies_emp ON process_anomalies(employee_id, detected_at);\n\n-- System settings for desktop activity policy\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('idle_threshold_minutes', '5', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('lock_screen_grace_minutes', '5', 0, 'system');\n\nINSERT OR IGNORE INTO org_settings (key, value, updated_at, updated_by)\nVALUES ('approved_work_processes', 'code.exe,chrome.exe,slack.exe,ms-teams.exe,teams.exe,excel.exe,winword.exe,powerpnt.exe,figma.exe,cursor.exe,webstorm64.exe,idea64.exe,notepad.exe,outlook.exe,postman.exe,terminal.exe,powershell.exe,cmd.exe,devenv.exe,Code,Google Chrome,Slack,Microsoft Teams,Microsoft Excel,Microsoft Word,Figma,Cursor,WebStorm,IntelliJ IDEA,Notes,Terminal,iTerm2', 0, 'system');\n"
  },
  {
    "id": "015_app_usage.sql",
    "sql": "-- Workstation App Usage\nCREATE TABLE IF NOT EXISTS workstation_app_usage (\n  id TEXT PRIMARY KEY,\n  employee_id TEXT NOT NULL REFERENCES employees(id) ON DELETE CASCADE,\n  device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,\n  session_date TEXT NOT NULL,\n  app_name TEXT NOT NULL,\n  active_seconds INTEGER NOT NULL DEFAULT 0,\n  last_used_at INTEGER NOT NULL,\n  UNIQUE(device_id, session_date, app_name)\n);\n\nCREATE INDEX IF NOT EXISTS idx_app_usage_emp_date ON workstation_app_usage(employee_id, session_date);\n"
  }
